const examCategoryOrder=["Mental status", "Cranial nerves", "Motor system", "Sensory", "Coordination", "Reflexes", "Gait / station", "Skull / spine / meninges", "Miscellaneous"];
const examCategoryIds={"Mental status": ["nonfluent", "fluent", "aphasia", "neglect"], "Cranial nerves": ["rField", "lField", "field", "rface", "lface", "centralNystagmus", "dysarthria"], "Motor system": ["rarm", "larm", "rleg", "lleg", "armPred", "equalMotor", "spastic", "rigidity", "brady"], "Sensory": ["rCorticalSensory", "lCorticalSensory"], "Coordination": ["rfn", "lfn", "rhs", "lhs", "rram", "lram", "intention", "truncal"], "Reflexes": ["hyper", "rclonus", "lclonus", "rplantar", "lplantar", "hoffmann"], "Gait / station": ["wideGait", "tandem", "eyesOpen", "scissor", "circum", "shuffle", "magnetic"], "Skull / spine / meninges": [], "Miscellaneous": ["crossed"]};
features.forEach(f=>{const group=examCategoryOrder.find(g=>examCategoryIds[g].includes(f.id));if(group)f.group=group;});
features.sort((a,b)=>examCategoryOrder.indexOf(a.group)-examCategoryOrder.indexOf(b.group));
for(const f of features){if(['nonfluent','fluent'].includes(f.id))for(const l of ['Spinal cord','Root','Plexus','Nerve','NMJ','Muscle'])f.weights[l]=-4;if(['rField','lField','rCorticalSensory','lCorticalSensory'].includes(f.id))for(const l of ['Cerebellum','Spinal cord','Root','Plexus','Nerve','NMJ','Muscle'])f.weights[l]=-3;if(['aphasia','neglect','field','level'].includes(f.id))f.weights.Cerebellum=-4;if(f.id==='hyper')f.weights.Cerebellum=-2;}
const cases={"frontalLanguage": ["nonfluent", "rface", "rarm"], "posteriorLanguage": ["fluent", "rField"], "rightParietal": ["neglect", "lCorticalSensory"], "cerebellarRight": ["rfn", "rhs", "rram"], "cerebellarLeft": ["lfn", "lhs", "lram"], "axial": ["truncal", "wideGait", "eyesOpen"], "pyramidal": ["rclonus", "rplantar", "spastic"], "parkinsonian": ["shuffle", "rigidity", "brady"], "cortical": ["rface", "rarm", "aphasia"], "deep": ["rface", "rarm", "rleg", "equalMotor", "hyper"], "crossed": ["crossed", "hyper"]};
