const examReferences={"Mental status": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-mental-status", "Cranial nerves": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-the-cranial-nerves", "Motor system": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-the-motor-system", "Sensory": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-sensation", "Coordination": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-gait-stance-and-coordination", "Reflexes": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-reflexes", "Gait / station": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/how-to-assess-gait-stance-and-coordination", "Skull / spine / meninges": "https://www.msdmanuals.com/professional/neurologic-disorders/meningitis/overview-of-meningitis", "Miscellaneous": "https://www.msdmanuals.com/professional/neurologic-disorders/neurologic-examination/introduction-to-the-neurologic-examination"};
const categoryGroups=examCategoryOrder.filter(group=>features.some(f=>f.group===group));
const simpleFindingIds=new Set(['aphasia','neglect','rField','lField','field','rface','lface','dysarthria','rarm','larm','rleg','lleg','rHemiSensory','lHemiSensory','rfn','lfn','rhs','lhs']);
let findingMode='simple';
function isFindingVisible(id){return findingMode==='expanded'||simpleFindingIds.has(id)||chosen.has(id);}
function updateFindingVisibility(){
 document.querySelectorAll('#features .finding').forEach(row=>{row.hidden=!isFindingVisible(row.querySelector('input').value);});
 document.querySelectorAll('.feature-category').forEach(category=>{category.hidden=![...category.querySelectorAll('.finding')].some(row=>!row.hidden);});
 document.querySelectorAll('[data-finding-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.findingMode===findingMode)));
 const extra=features.filter(f=>chosen.has(f.id)&&!simpleFindingIds.has(f.id)).length;
 $('#finding-mode-note').textContent=findingMode==='simple'?'Core localization findings · NIHSS-style, not an NIHSS score'+(extra?` · ${extra} expanded selection${extra===1?'':'s'} retained`:''):'All brain-relevant localization findings';
}
$('#finding-mode').addEventListener('click',e=>{const button=e.target.closest('[data-finding-mode]');if(!button)return;findingMode=button.dataset.findingMode;updateFindingVisibility();});
$('#features').innerHTML=categoryGroups.map((group,index)=>{
 const members=features.filter(f=>f.group===group),count=members.filter(f=>chosen.has(f.id)).length;
 return `<details class="feature-category" data-category="${index}" ${count?'open':''}><summary><span>${group}</span><span class="category-count" aria-label="${count} selected">${count||''}</span></summary><div class="category-findings"><a class="exam-reference" href="${examReferences[group]}" target="_blank" rel="noreferrer">Examination reference ↗</a>${members.map(f=>`<label class="finding"><input type="checkbox" value="${f.id}" ${chosen.has(f.id)?'checked':''}><span>${f.label}</span></label>`).join('')}</div></details>`;
}).join('');
function updateCategoryCounts(){document.querySelectorAll('.feature-category').forEach(category=>{const count=features.filter(f=>f.group===categoryGroups[Number(category.dataset.category)]&&chosen.has(f.id)).length;const badge=category.querySelector('.category-count');badge.textContent=count||'';badge.setAttribute('aria-label',`${count} selected`);});}
$('#expand-categories').addEventListener('click',()=>document.querySelectorAll('.feature-category').forEach(c=>c.open=true));
$('#collapse-categories').addEventListener('click',()=>document.querySelectorAll('.feature-category').forEach(c=>c.open=false));
function calculate(ids){const fs=features.filter(f=>ids.has(f.id)).map(f=>({...f,weights:(((f.id==='rDrift'&&ids.has('rarm'))||(f.id==='lDrift'&&ids.has('larm')))|| (f.id==='aphasia'&&(ids.has('nonfluent')||ids.has('fluent')))||(f.id==='field'&&(ids.has('rField')||ids.has('lField'))))?{}:f.weights}));const scores=Object.fromEntries(levels.map(l=>[l,fs.reduce((s,f)=>s+(f.weights[l]||0),0)]));return{fs,scores,rank:[...levels].sort((a,b)=>scores[b]-scores[a])}}
const syndrome={Cerebellum:['Cerebellar / cerebellar-connection pattern','Consider vascular disease if abrupt; toxic or medication effects, inflammation, structural disease, and degenerative or inherited ataxias according to course. Cerebellar peduncle lesions can mimic a hemispheric pattern.'],Cortex:['Cerebral cortical / network pattern','Vascular lesion if abrupt; seizure-related dysfunction if episodic or postictal; inflammatory or structural lesions according to course.'],Subcortex:['Deep hemispheric motor / sensory pattern','Small-vessel ischemia is one possibility if acute. Hemorrhage, demyelination and structural lesions can affect the same pathways.'],Brainstem:['Brainstem long-tract / cranial-nerve pattern','Vascular, inflammatory, demyelinating or structural processes; specific nerve findings and imaging determine the level.'],'Spinal cord':['Myelopathic pattern','Compressive, inflammatory and vascular cord processes. Sphincter findings also require conus / cauda equina assessment.'],Root:['Radicular pattern','Mechanical compression, inflammatory radiculopathy or other root lesions. Root number and level are not assigned by this model.'],Plexus:['Plexopathy-compatible pattern','Traumatic, inflammatory or infiltrative plexus disease; multiple radiculopathies and mononeuropathies remain alternatives.'],Nerve:['Peripheral neuropathic pattern','Entrapment or traumatic focal neuropathy for one nerve; metabolic, toxic or immune neuropathy for a generalized pattern.'],NMJ:['Neuromuscular transmission pattern','Myasthenia gravis and other transmission disorders. Reflex, autonomic, pupil and exposure findings help distinguish alternatives.'],Muscle:['Myopathic pattern','Inflammatory, endocrine, toxic, metabolic or inherited muscle disease; consider neuromuscular transmission disorders.']};
function render(){const {fs,scores,rank}=calculate(chosen),has=id=>id==='aphasia'?(chosen.has('aphasia')||chosen.has('nonfluent')||chosen.has('fluent')):id==='field'?(chosen.has('field')||chosen.has('rField')||chosen.has('lField')):chosen.has(id),top=rank[0],best=scores[top],ties=rank.filter(l=>scores[l]===best),positive=fs.filter(f=>(f.weights[top]||0)>0),negative=fs.filter(f=>(f.weights[top]||0)<0),onset=$('#onset').value,dom=$('#dominance').value;const ataxiaRight=['rfn','rhs','rram'].some(has),ataxiaLeft=['lfn','lhs','lram'].some(has);const right=['rface','rarm','rleg','rclonus','rplantar','rDrift'].some(has),left=['lface','larm','lleg','lclonus','lplantar','lDrift'].some(has);
$('#count').textContent=fs.length;updateCategoryCounts();updateFindingVisibility();const gaps=[];const conflicts=[];
if(has('nonfluent')&&has('fluent'))conflicts.push('Nonfluent and fluent language profiles conflict for the same assessment; reconcile the observations.');
if(has('armPred')&&has('equalMotor'))conflicts.push('Face–arm predominance and proportionate face–arm–leg weakness describe conflicting distributions.');
if(has('aphasia')&&((dom==='left'&&left&&!right)||(dom==='right'&&right&&!left)))conflicts.push('Known language dominance and motor laterality do not align with a simple unilateral hemispheric lesion.');
if(has('aphasia')&&left&&!right&&dom==='unknown')gaps.push('Left-sided motor signs with aphasia requires checking language dominance and whether more than one lesion is involved.');
if(right&&left)gaps.push('Bilateral deficits limit unilateral localization. Confirm distribution and consider bilateral or multifocal disease.');
if(!has('field'))gaps.push('Visual fields not provided.');
if(!['rHemiSensory','lHemiSensory','rCorticalSensory','lCorticalSensory'].some(has))gaps.push('Sensory examination not provided.');
if(!['hyper','rclonus','lclonus','rplantar','lplantar','hoffmann'].some(has))gaps.push('Reflexes and plantar responses not provided.');
if(onset==='unknown')gaps.push('Time course not provided; etiology cannot be prioritized.');
if(has('aphasia')&&dom==='unknown')gaps.push('Language dominance is unknown; left dominance is common, not guaranteed.');
if(ataxiaRight||ataxiaLeft||has('intention')){gaps.push('Confirm coordination was not limited by weakness, pain, vision or comprehension.');gaps.push('Joint-position sense was not specifically reported; sensory ataxia remains possible.');if(['rface','rarm','rleg','lface','larm','lleg'].some(has))gaps.push('Reported weakness may confound coordination testing. Cerebellar laterality is based on dysmetria, not on the side of weakness.');}
if((has('rHemiSensory')&&has('rCorticalSensory'))||(has('lHemiSensory')&&has('lCorticalSensory')))conflicts.push('Primary sensory loss conflicts with cortical sensory testing labeled elementary sensation intact on the same side. Clarify modality and distribution.');
if(has('rHemiSensory')||has('lHemiSensory'))gaps.push('Confirm face–body distribution and sensory modality; cerebral, thalamic and upper brainstem pathways remain alternatives.');
const mapState={ids:[...chosen],top,best,ties,conflicts:conflicts.length,dominance:dom,right,left,ataxiaRight,ataxiaLeft};const anatomy=typeof inferAnatomy==='function'?inferAnatomy(mapState):null;if(anatomy?.sideConflict)conflicts.push('Lateralizing motor, sensory, visual, attention or language findings disagree; a single unilateral lesion is not established.');
negative.forEach(f=>conflicts.push(`${f.label} is not well explained by an isolated ${top.toLowerCase()} lesion.`));
let title=top,desc='Highest rule support among the modeled levels. This is a localization hypothesis, not a diagnosis.';
if(top==='Cortex'&&best>0){title=right&&!left?'Left cerebral hemisphere':left&&!right?'Right cerebral hemisphere':has('aphasia')?'Dominant cerebral hemisphere':'Cerebral cortical network';desc=has('aphasia')?'Language-network involvement is supported. Motor laterality and known language dominance must agree before assigning a single hemispheric lesion.':'Cortical or connected cerebral networks offer a possible explanation for the selected pattern.';if(has('aphasia')&&has('rface')&&has('rarm')&&!left&&!anatomy?.sideConflict){desc='Left hemispheric language and motor network involvement is coherent if language is left-dominant. An MCA-territory pattern is compatible; an arterial lesion is not established.';}}
if(top==='Cerebellum'){title=ataxiaRight&&!ataxiaLeft?'Right cerebellar circuitry':ataxiaLeft&&!ataxiaRight?'Left cerebellar circuitry':has('truncal')?'Axial cerebellar circuitry':'Cerebellar circuitry';desc='A cerebellar or connected pathway pattern is compatible. Limb signs generally support the same-side cerebellar circuitry; weakness and sensory loss must be excluded as confounders. No specific lobule or vascular territory is assigned.';}
if(top==='Subcortex')title=right&&!left?'Left subcortical motor pathways':left&&!right?'Right subcortical motor pathways':'Subcortical pathways';
if(top==='Cortex'&&anatomy){title=anatomy.sideConflict?'Cerebral network — conflicting lateralization':anatomy.side?anatomy.side[0].toUpperCase()+anatomy.side.slice(1)+' cerebral hemisphere':has('aphasia')?'Dominant cerebral language network':'Cerebral cortical network';}
if(top==='Subcortex'&&['shuffle','rigidity','brady'].some(has)){title='Basal ganglia–motor network';desc='An extrapyramidal pattern is compatible. The model groups this under subcortex; it does not establish a particular nucleus or Parkinson disease.';}
if(!fs.length){title='Start with an observed finding';desc='Select features on the left, or load an example pattern. No localization is inferred without findings.';}
else if(best<=0){title='No supported localization';desc='The selected findings do not support a coherent level in this limited model. Reassess the pattern and consider unmodeled or multifocal disease.';}
else if(ties.length>1){title='Localization remains unresolved';desc=`Equal rule support: ${ties.join(', ')}. Add discriminating findings before favoring one level.`;}
else if(conflicts.length){desc+=' Conflicting observations remain; the leading score does not resolve them.';}
$('#result').innerHTML=`<div class="eyebrow">${!fs.length?'ANATOMICAL REASONING':conflicts.length?'LEADING LOCALIZATION · UNRESOLVED CONFLICTS':ties.length>1?'ANATOMICAL REASONING':'MOST COHERENT LOCALIZATION'}</div><h2>${title}</h2><p>${desc}</p><span class="badge">${!fs.length?'Awaiting observations':best<=0?'Insufficient support':ties.length>1?'Tied anatomical levels':conflicts.length?'Single-lesion fit is limited':'Relative support · '+(best>0?'+':'')+best+' rule points'}</span>`;
$('#constraints').innerHTML=fs.length?fs.map((f,i)=>`<div class="constraint"><span class="num">${String(i+1).padStart(2,'0')}</span><div><strong>${f.label}</strong><p>${f.reason}</p>${!Object.keys(f.weights).length?'<small class=clinical-context>Overlapping evidence · no additional points</small>':''}</div></div>`).join(''):'<p class="hint">No findings selected.</p>';
if((has('rface')&&has('rarm')||has('lface')&&has('larm'))&&!has('crossed'))$('#constraints').innerHTML+='<div class="constraint"><span class="num">↳</span><div><strong>Same-side face and limb involvement</strong><p>This does not form the classic crossed cranial-nerve / limb pattern. Brainstem disease is not excluded.</p></div></div>';
$('#support').innerHTML=fs.length&&best>0?positive.map(f=>`<p>${f.label}<small> · +${f.weights[top]}</small></p>`).join(''):'<p>No supporting observations yet.</p>';
$('#gaps').innerHTML=fs.length?conflicts.map(t=>`<p class="conflict">${t}</p>`).join('')+gaps.map(t=>`<p class="gap">${t}</p>`).join(''):'<p class="gap">No examination data provided.</p>';
let diff=syndrome[top];let syndromeName=diff[0];if(top==='Subcortex'&&['shuffle','rigidity','brady'].some(has)){syndromeName='Parkinsonian motor pattern candidate';diff=[syndromeName,'Consider degenerative, medication-induced and vascular parkinsonism according to history and examination. Shuffling alone does not establish parkinsonism.'];}if(top==='Cortex'&&has('aphasia')&&(has('rarm')||has('larm')))syndromeName='Dominant hemispheric language–motor syndrome';if(top==='Subcortex'&&has('equalMotor'))syndromeName='Pure motor syndrome candidate — requires confirming no sensory, visual or cortical deficit';
$('#differential').innerHTML=!fs.length||best<=0||ties.length>1?'<p>Add discriminating findings to establish a candidate anatomical pattern before considering an etiologic differential.</p>':`<h3>${syndromeName}</h3><p>${conflicts.length?'Provisional only: the listed contradictions prevent a clean single-lesion explanation.':'Anatomical compatibility does not establish a cause.'}</p><ul><li>${diff[1]}</li><li>${onset==='sudden'?'Abrupt onset increases concern for vascular disease in central patterns, but does not prove ischemia.':onset==='subacute'?'A subacute course raises inflammatory, infectious or evolving structural possibilities, depending on the examination.':onset==='chronic'?'A chronic course shifts attention toward structural, degenerative, metabolic and inherited causes according to the pattern.':onset==='fluctuating'?'Fluctuation can occur with transmission disorders, seizures, migraine and other episodic processes; anatomy remains essential.':'Record onset, evolution and associated symptoms before ranking causes.'}</li></ul>`;
let alert='';if(onset==='sudden'&&fs.length)alert='Sudden neurological deficits require urgent clinical assessment. This educational matcher cannot rule out stroke or other emergencies.';$('#alert').innerHTML=alert?`<div class="notice">${alert}</div>`:'';
if(!inspected)inspected=top;const max=Math.max(...Object.values(scores).map(Math.abs),1);$('#hierarchy').innerHTML=levels.map((l,i)=>`<button class="node ${l===inspected?'selected':''}" data-level="${l}" aria-pressed="${l===inspected}"><span class="node-row"><span>${String(i+1).padStart(2,'0')} &nbsp; ${l}</span><b>${scores[l]>0?'+':''}${scores[l]}</b></span><span class="bar ${scores[l]<0?'negative':''}"><span style="width:${Math.abs(scores[l])/max*100}%"></span></span></button>`).join('');
if(typeof window!=='undefined'){window.neuroState={ids:[...chosen],top,best,ties,scores,inspected,conflicts:conflicts.length,dominance:dom,right,left,ataxiaRight,ataxiaLeft};window.dispatchEvent(new CustomEvent('neuro-change',{detail:window.neuroState}));}const impacts=fs.filter(f=>f.weights[inspected]);$('#inspection').innerHTML=`<strong>${inspected} · evidence audit</strong>${impacts.length?impacts.map(f=>`<p>${f.weights[inspected]>0?'+':''}${f.weights[inspected]} &nbsp; ${f.label}</p>`).join(''):'<p>No selected finding changes support for this level.</p>'}<p>Points express rules, not clinical likelihood.</p>`;
}
$('#features').addEventListener('change',e=>{if(e.target.type!=='checkbox')return;e.target.checked?chosen.add(e.target.value):chosen.delete(e.target.value);$('#case').value='custom';inspected=null;render()});
$('#case').addEventListener('change',e=>{chosen=new Set(cases[e.target.value]||[]);$('#onset').value='unknown';$('#dominance').value='unknown';inspected=null;sync();document.querySelectorAll('.feature-category').forEach(c=>{c.open=[...c.querySelectorAll('input')].some(i=>i.checked)});});
function sync(){document.querySelectorAll('#features input').forEach(i=>i.checked=chosen.has(i.value));render()}
$('#clear').addEventListener('click',()=>{chosen.clear();$('#case').value='custom';$('#onset').value='unknown';$('#dominance').value='unknown';inspected=null;sync()});
$('#onset').addEventListener('change',render);$('#dominance').addEventListener('change',render);$('#hierarchy').addEventListener('click',e=>{const node=e.target.closest('[data-level]');if(node){inspected=node.dataset.level;render();document.querySelector(`[data-level="${inspected}"]`).focus()}});render();
if(typeof module!=='undefined')module.exports={calculate,features,cases};
